/* s84: off-screen briefs skip style and layout (html.cv, set by script after load), so toggling study mode
   restyles only what is on screen; it was a whole-page recalculation of about 120,000 elements, felt as a freeze */
html.cv .brief{content-visibility:auto;contain-intrinsic-size:auto 7000px}
@media print{html.cv .brief{content-visibility:visible}}
#rvpanel[hidden]{display:none!important}

window.__axMaskObserver=new MutationObserver(function(){
      /* s84: only when study mode itself flips, not on every body class change */
      var s=document.body.classList.contains('study');
      if(s===window.__axLastStudy) return; window.__axLastStudy=s; syncMaskRegions();
    });
    window.__axLastStudy=document.body.classList.contains('study');
